// Maps website events -> Google-Form-derived registration forms.
//
// The questions themselves live in eventForms.json, which is generated by
//   npm run scrape-forms
// (it reads every Google Form listed in scripts/scrape-forms.mjs).
//
// An event with no form here (or whose form could not be scraped) keeps the
// old 1-click / profile registration flow.
//
// Value of each entry is either:
//   'form-slug'                                  -> one form
//   [{ label: 'Men\'s', slug: '...' }, ...]      -> user first picks a variant
import FORMS from './eventForms.json';

const normalize = (name = '') =>
  name
    .replace(/^[^A-Za-z0-9]+/, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();

const MAP = {
  // Academic
  'basic life support workshop': 'trauma-code-bls-acls-workshop',
  'suture workshop': 'suture-workshop',
  // 'preclinical quiz': the Linktree link for it opens the PARA-clinical form (same link).
  // Enable once the college gives the real pre-clinical form link and it is scraped.
  // 'preclinical quiz': 'pre-clinical-quiz',
  'paraclinical quiz': 'para-clinical-quiz',
  'clinical quiz': 'clinical-quiz',
  'case presentation': 'case-presentation',

  // Literary
  'agora (debate)': 'agora-debate',
  'hridaya (poetry, shayari & elocution)': 'hridaya-premchand-kalam-aur-kalpana',
  'spell bee': 'spell-bee',
  'cryptic crossword': 'cryptic-crossword',
  'medimelody (song se syndrome)': 'medimelody-song-se-syndrome',
  'pop-culture quiz': 'popverse',
  'general quiz': 'general-quiz',

  // Sports
  cricket: [
    { label: "Men's Cricket", slug: 'men-s-cricket' },
    { label: "Women's Cricket", slug: 'women-s-cricket' },
  ],
  football: 'football',
  volleyball: 'volleyball',
  badminton: 'badminton',
  kabaddi: [
    { label: "Men's Kabaddi", slug: 'men-s-kabbadi' },
    { label: "Women's Kabaddi", slug: 'women-s-kabaddi' },
  ],
  chess: 'chess',
  'table tennis': 'table-tennis',
  carrom: 'carrom',
  athletics: 'athletics',
  "rubik's mania": 'rubik-s-cube',
  bgmi: 'bgmi',

  // Cultural
  'swarmay (singing)': 'swarmay-singing',
  'flamenco (dancing)': 'flamenco-dance',
  'cinematica (film making)': 'cinematica',
  abhinay: 'abhinay-theatre-drama',
  'nazariya (photography)': 'nazariya-photography',
  'got talent': 'got-talent',
  'memecentral (meme competition)': 'memecentral',
  'stardust (bollywood recreation)': 'stardust',
  'dharohar (folklore)': 'dharohar',
  'venust (fashion show)': 'venust-fashion-show',

  // Art
  'chitraganga (painting)': 'chitranganga-painting',
  'doodle dreams (doodle art)': 'doodle-dreams',
  'sculpture spectacle (clay art)': 'sculpture-spectacle-clay-art',
  'tattoo titans (tattoo art)': 'tattoo-titans',
  'mehendi delights (mehendi)': 'mehendi-delights',
  'aripan (rangoli)': [
    { label: 'Aripan (Online)', slug: 'aripan-online' },
    { label: 'Aripan (Offline)', slug: 'aripan-offline' },
  ],
  'recycled wonders (waste art)': 'recycled-wonders-waste-art',
  'cyber-creation (digital art)': 'cyber-creation-digital-art',
  'tee-splash (t-shirt painting)': 'tee-splash',
  'magic mask (face painting)': 'magic-mask-face-painting',
};

/**
 * Returns [{ label, slug, form }] for an event, only including forms that
 * were actually scraped. Empty array => event has no custom form.
 */
export function getEventForms(eventName) {
  const entry = MAP[normalize(eventName)];
  if (!entry) return [];
  const list = Array.isArray(entry) ? entry : [{ label: null, slug: entry }];
  return list
    .filter((v) => FORMS[v.slug] && (FORMS[v.slug].fields || []).length > 0)
    .map((v) => ({ label: v.label, slug: v.slug, form: FORMS[v.slug] }));
}

export const hasEventForm = (eventName) => getEventForms(eventName).length > 0;
